  ROWS.push(...[{"p": "leaves", "b": 0, "n": "Pacing Your Day", "d": "Plan today's energy like a budget: one must, one want, and rest in between.", "m": ["Z", "10 min", "S", ""], "g": {"why": "When energy is limited, spending it on purpose helps you do what matters most and leaves room to recover. Planning rest before you need it keeps good days from turning into hard ones.", "today": "Write three lines: one thing you must do, one thing you want to do, and when you will rest. Do them in that order, resting between.", "build": "Notice which times of day you have the most energy, and put what matters most there. Keep a short list of what can wait.", "hard": "If even one thing feels like too much, the plan for today is rest. That counts as tending."}, "f": {"life": ["health", "pain", "serious", "moving", "mind", "memory", "gentle"], "adapt": "On a hard day, choose one thing and let the rest wait. That is a full plan."}}, {"p": "leaves", "b": 0, "n": "Rest Before You're Spent", "d": "Take a planned rest break before you run out, not after.", "m": ["Z", "10 min", "S", ""], "g": {"why": "Resting only after you crash makes recovery longer. Short planned breaks spread through the day can keep energy steadier.", "today": "Pick two times today for a ten minute rest, and set a gentle reminder. Rest even if you feel fine.", "build": "Keep the same rest times for two weeks and notice how your evenings feel.", "hard": "If rest brings guilt, say it plainly: resting is part of caring for my body. Rest is tending too."}, "f": {"life": ["pain", "health", "serious", "mind", "close", "gentle"], "adapt": "Lying down, eyes closed, or sitting with your feet up all count."}}, {"p": "bark", "b": 0, "n": "Hard-Day Plan", "d": "Write a short plan for hard days: what can wait, who to tell, and what comforts you.", "m": ["W", "15 min", "E", ""], "g": {"why": "Hard days come with less energy for decisions. A plan made on a better day does the thinking for you.", "today": "Write three short lists: what can wait, who to tell and how, and three things that comfort you, like a show, a blanket, or a voice you love.", "build": "Share the plan with one person who helps you, and update it after a hard day with what helped.", "hard": "If writing is hard, say it aloud and let someone write it down, or record it on your phone."}, "f": {"life": ["health", "pain", "serious", "mind", "memory", "close", "gentle"], "adapt": "Make it on a good day, keep it where you rest, and let someone read it to you when you need it."}}, {"p": "leaves", "b": 0, "n": "Appointment Prep", "d": "Before a visit, write what has changed, three questions, and what matters most to you.", "m": ["L", "10 min", "S", ""], "g": {"why": "Appointments go fast. Coming with your questions and what matters to you helps you leave with what you came for.", "today": "Write what has changed since your last visit, the three questions that matter most, and one thing you want your care team to know about your life.", "build": "Bring the list to every visit, and write down the answers or ask someone to. Ask what to watch for and who to call.", "hard": "If you forget a question, it is fine to call or message after. You can also ask for the visit notes."}, "f": {"life": ["health", "serious", "pain", "memory", "hearing", "seeing", "learning", "mind", "moving"], "adapt": "Record it on your phone, ask for an interpreter or large print, or bring someone to take notes."}}, {"p": "bark", "b": 0, "n": "Body Kindness Scan", "d": "Thank each part of your body for what it does today, skipping any part you choose.", "m": ["B", "5 min", "S", ""], "g": {"why": "When a body hurts or works differently, it is easy to notice only what is hard. Kind attention to what still serves you can soften the day.", "today": "Start at your hands or your breath. Name one thing each part did for you today, and say thank you. Skip any part you choose.", "build": "Try it at the same time each day, like before sleep, for two weeks.", "hard": "If any part brings up pain or hard feelings, move on, or stop and rest. Your choice is the practice."}, "f": {"life": ["pain", "moving", "health", "serious", "mind", "gentle"], "adapt": "Lying down or seated. Skip any part, and stay with the parts that feel neutral or good."}}, {"p": "branches", "b": 0, "n": "Say What You Need", "d": "Ask for one thing that helps, in one clear sentence: a seat, captions, a slower pace, or a quiet room.", "m": ["R", "5 min", "E", ""], "g": {"why": "People often want to help but do not know how. One clear sentence makes it easy for them to say yes.", "today": "Finish this sentence for one place you go this week: It helps me when you... Say it, show it, or send it.", "build": "Keep a short list of what helps you, ready to share with a new teacher, boss, doctor, or friend.", "hard": "If asking feels hard, start with someone safe. Asking for what helps is a strength, and you never owe anyone your whole story."}, "f": {"life": ["hearing", "seeing", "moving", "autism", "learning", "health", "pain", "mind"], "adapt": "Write it on a card or in your phone notes to show, or ask someone you trust to say it with you."}}, {"p": "bark", "b": 0, "n": "Quiet the Senses", "d": "Lower the light and sound for a few minutes: headphones, a dim room, or a soft blanket.", "m": ["Z", "5 min", "E", ""], "g": {"why": "Bright light, noise, and crowds can wear a body and mind down fast. A few quiet minutes give your senses a rest.", "today": "Find the quietest spot you can. Dim the light, put on headphones or earplugs, and breathe slowly for five minutes.", "build": "Plan a quiet reset after busy times, like after work, class, or a family gathering.", "hard": "If you cannot leave the room, close your eyes, look at one still thing, or step into a hallway for a minute."}, "f": {"life": ["autism", "mind", "pain", "learning", "serious", "gentle"], "adapt": "Keep a small kit ready: headphones, sunglasses, and something soft to hold."}}, {"p": "trunk", "b": 0, "n": "Worth Beyond Doing", "d": "Name three ways you matter that have nothing to do with what you can do today.", "m": ["W", "5 min", "E", ""], "g": {"why": "When illness or a disability changes what you can do, it can feel like your worth changes too. It does not. Naming what you are, not only what you do, steadies that.", "today": "Write or say three ways you matter: how you love, what you notice, what you carry, who you are to someone.", "build": "Keep the list where you will see it, and add to it when someone tells you what you mean to them.", "hard": "If you cannot think of any today, ask someone who loves you. Their answer counts."}, "f": {"life": ["health", "pain", "serious", "moving", "close", "mind", "memory", "gentle"], "adapt": "Say them aloud, or ask someone who loves you to name one with you."}}, {"p": "branches", "b": 0, "n": "A Break for the Helper", "d": "If you help care for someone, plan one real break this week and let someone else cover.", "m": ["Z", "60 min", "S", ""], "g": {"why": "People who care for someone they love often go a long time without a real break. Rest helps you keep going, and helps the person you love too.", "today": "Name one hour this week and one person who could cover. Ask them today.", "build": "Make it a standing break, the same time each week.", "hard": "If no one can cover, ask your clinic, a faith community, or a local caregiver program about respite."}, "f": {"life": ["close"], "adapt": "Even twenty minutes counts. A walk, a nap, or a coffee with a friend."}}]);
